/**
 * /automod Slash Command
 * Server configuration for standard AutoMod rules:
 * - /automod status: View active filters & thresholds
 * - /automod toggle: Enable/disable specific AutoMod modules
 * - /automod sync: Provision Discord's official server-side native AutoMod rules
 */
import { SlashCommandBuilder, PermissionFlagsBits, EmbedBuilder, MessageFlags, } from "discord.js";
export const autoModCommand = {
    data: new SlashCommandBuilder()
        .setName("automod")
        .setDescription("Configure AegisMod Standard AutoMod protection rules and Discord native sync")
        .setDefaultMemberPermissions(PermissionFlagsBits.ManageGuild)
        .addSubcommand((sub) => sub.setName("status").setDescription("View current AutoMod rule statuses and thresholds"))
        .addSubcommand((sub) => sub
        .setName("toggle")
        .setDescription("Enable or disable a specific AutoMod rule")
        .addStringOption((opt) => opt
        .setName("rule")
        .setDescription("The AutoMod rule to configure")
        .setRequired(true)
        .addChoices({ name: "Anti-Invite Links", value: "antiInvite" }, { name: "Anti-Phishing & Scam Links", value: "antiPhishing" }, { name: "Anti-Mass Mentions", value: "antiMassMention" }, { name: "Anti-Spam & Flood Control", value: "antiSpam" }, { name: "Anti-Excessive Caps", value: "antiCaps" }, { name: "Anti-Zalgo & Glitch Text", value: "antiZalgo" }, { name: "Anti-Banned Words & Slurs", value: "antiBannedWords" }))
        .addBooleanOption((opt) => opt.setName("enabled").setDescription("Whether the rule should be enabled").setRequired(true)))
        .addSubcommand((sub) => sub
        .setName("sync")
        .setDescription("Sync Discord Native AutoMod rules directly to the server")),
    async execute(interaction, autoModService) {
        if (!interaction.guild) {
            return interaction.reply({ content: "This command can only be used in a server.", flags: MessageFlags.Ephemeral });
        }
        const subcommand = interaction.options.getSubcommand();
        const guildId = interaction.guild.id;
        if (subcommand === "status") {
            const config = autoModService.getConfig(guildId);
            const embed = new EmbedBuilder()
                .setTitle("🛡️ AegisMod - Standard AutoMod Status")
                .setDescription("Deterministic local filters running alongside Gemini AI to ensure zero-latency protection against spam, malicious links, and server raids.")
                .setColor(0x5865f2)
                .addFields({
                name: "🔗 Anti-Invite Links",
                value: config.antiInvite ? "✅ **Enabled** (Deletes unauthorized `discord.gg` links)" : "❌ **Disabled**",
                inline: true,
            }, {
                name: "🎣 Anti-Phishing & Scams",
                value: config.antiPhishing ? "✅ **Enabled** (24h timeout on fake Nitro/Steam scams)" : "❌ **Disabled**",
                inline: true,
            }, {
                name: "📣 Anti-Mass Mentions",
                value: config.antiMassMention ? `✅ **Enabled** (Limit: ${config.mentionThreshold} mentions)` : "❌ **Disabled**",
                inline: true,
            }, {
                name: "🌊 Anti-Spam / Flood",
                value: config.antiSpam
                    ? `✅ **Enabled** (Max ${config.spamMessageThreshold} msgs in ${config.spamIntervalMs / 1000}s)`
                    : "❌ **Disabled**",
                inline: true,
            }, {
                name: "🔠 Anti-Excessive Caps",
                value: config.antiCaps ? `✅ **Enabled** (>=${config.capsPercentage}% uppercase on len >=${config.capsMinLength})` : "❌ **Disabled**",
                inline: true,
            }, {
                name: "🔣 Anti-Zalgo & Glitch Text",
                value: config.antiZalgo ? "✅ **Enabled** (Blocks client-lagging unicode characters)" : "❌ **Disabled**",
                inline: true,
            }, {
                name: "🚫 Zero-Tolerance Slurs",
                value: config.antiBannedWords ? "✅ **Enabled** (Instant local leetspeak interception)" : "❌ **Disabled**",
                inline: true,
            })
                .setFooter({ text: "Use /automod toggle <rule> <enabled> to adjust settings | /automod sync for native Discord rules" })
                .setTimestamp();
            return interaction.reply({ embeds: [embed], flags: MessageFlags.Ephemeral });
        }
        if (subcommand === "toggle") {
            const rule = interaction.options.getString("rule", true);
            const enabled = interaction.options.getBoolean("enabled", true);
            autoModService.updateConfig(guildId, { [rule]: enabled });
            return interaction.reply({
                content: `✅ Updated AutoMod rule **${rule}**: **${enabled ? "ENABLED" : "DISABLED"}**.`,
                flags: MessageFlags.Ephemeral,
            });
        }
        if (subcommand === "sync") {
            await interaction.deferReply({ flags: MessageFlags.Ephemeral });
            const result = await autoModService.syncDiscordNativeRules(interaction.guild);
            const embed = new EmbedBuilder()
                .setTitle("⚡ Discord Native AutoMod Provisioning")
                .setColor(result.errors.length > 0 ? 0xffaa00 : 0x57f287)
                .setDescription("Synced server-side AutoMod rules directly with Discord's infrastructure. These rules run on Discord's edge servers even before messages reach chat!")
                .addFields({ name: "New Rules Created", value: `${result.created}`, inline: true }, { name: "Existing Rules Verified", value: `${result.updated}`, inline: true }, {
                name: "Rules Installed",
                value: "• AegisMod - Native Anti-Mention Spam\n• AegisMod - Native Anti-Spam\n• AegisMod - Native High-Risk Keyword Filter",
            });
            if (result.errors.length > 0) {
                embed.addFields({
                    name: "⚠️ Warnings",
                    value: result.errors.slice(0, 3).join("\n"),
                });
            }
            return interaction.editReply({ embeds: [embed] });
        }
    },
};

/**
 * Traditional Moderation Commands
 * Slash commands: /ban, /kick, /mute, /warn, /cases
 */
import { SlashCommandBuilder, PermissionFlagsBits, EmbedBuilder, MessageFlags, } from "discord.js";
export const moderationCommands = [
    // 1. /ban command
    {
        data: new SlashCommandBuilder()
            .setName("ban")
            .setDescription("Ban a user from the server with audit logging")
            .addUserOption((opt) => opt.setName("target").setDescription("Member to ban").setRequired(true))
            .addStringOption((opt) => opt.setName("reason").setDescription("Reason for ban").setRequired(true))
            .addIntegerOption((opt) => opt
            .setName("prune_days")
            .setDescription("Days of message history to delete (0 to 7)")
            .setMinValue(0)
            .setMaxValue(7))
            .setDefaultMemberPermissions(PermissionFlagsBits.BanMembers),
        async execute(interaction, modService) {
            const targetUser = interaction.options.getUser("target", true);
            const reason = interaction.options.getString("reason", true);
            const pruneDays = interaction.options.getInteger("prune_days") ?? 1;
            const targetMember = interaction.guild?.members.cache.get(targetUser.id);
            if (!targetMember) {
                return interaction.reply({ content: "That user is not currently in this server.", flags: MessageFlags.Ephemeral });
            }
            await interaction.deferReply();
            const result = await modService.ban(interaction.member, targetMember, reason, pruneDays);
            if (!result.success) {
                return interaction.editReply({ content: `❌ Ban failed: ${result.error}` });
            }
            return interaction.editReply({
                content: `🔨 **${targetUser.tag}** has been banned.\n**Reason:** ${reason}`,
            });
        },
    },
    // 2. /kick command
    {
        data: new SlashCommandBuilder()
            .setName("kick")
            .setDescription("Kick a user from the server")
            .addUserOption((opt) => opt.setName("target").setDescription("Member to kick").setRequired(true))
            .addStringOption((opt) => opt.setName("reason").setDescription("Reason for kick").setRequired(true))
            .setDefaultMemberPermissions(PermissionFlagsBits.KickMembers),
        async execute(interaction, modService) {
            const targetUser = interaction.options.getUser("target", true);
            const reason = interaction.options.getString("reason", true);
            const targetMember = interaction.guild?.members.cache.get(targetUser.id);
            if (!targetMember) {
                return interaction.reply({ content: "That user is not currently in this server.", flags: MessageFlags.Ephemeral });
            }
            await interaction.deferReply();
            const result = await modService.kick(interaction.member, targetMember, reason);
            if (!result.success) {
                return interaction.editReply({ content: `❌ Kick failed: ${result.error}` });
            }
            return interaction.editReply({
                content: `👢 **${targetUser.tag}** has been kicked.\n**Reason:** ${reason}`,
            });
        },
    },
    // 3. /mute (timeout) command
    {
        data: new SlashCommandBuilder()
            .setName("mute")
            .setDescription("Mute (timeout) a user for a specific duration")
            .addUserOption((opt) => opt.setName("target").setDescription("Member to mute").setRequired(true))
            .addStringOption((opt) => opt
            .setName("duration")
            .setDescription("Duration format: 10m, 1h, 1d, 7d")
            .setRequired(true))
            .addStringOption((opt) => opt.setName("reason").setDescription("Reason for mute").setRequired(true))
            .setDefaultMemberPermissions(PermissionFlagsBits.ModerateMembers),
        async execute(interaction, modService) {
            const targetUser = interaction.options.getUser("target", true);
            const durationStr = interaction.options.getString("duration", true);
            const reason = interaction.options.getString("reason", true);
            const durationMs = modService.parseDurationString(durationStr);
            if (!durationMs) {
                return interaction.reply({
                    content: "Invalid duration format. Use: `10m` (minutes), `2h` (hours), `1d` (days).",
                    flags: MessageFlags.Ephemeral,
                });
            }
            const targetMember = interaction.guild?.members.cache.get(targetUser.id);
            if (!targetMember) {
                return interaction.reply({ content: "That user is not currently in this server.", flags: MessageFlags.Ephemeral });
            }
            await interaction.deferReply();
            const result = await modService.mute(interaction.member, targetMember, durationMs, reason);
            if (!result.success) {
                return interaction.editReply({ content: `❌ Mute failed: ${result.error}` });
            }
            return interaction.editReply({
                content: `🔇 **${targetUser.tag}** has been muted for **${modService.formatDuration(durationMs)}**.\n**Reason:** ${reason}`,
            });
        },
    },
    // 4. /warn command
    {
        data: new SlashCommandBuilder()
            .setName("warn")
            .setDescription("Issue an official logged warning to a member")
            .addUserOption((opt) => opt.setName("target").setDescription("Member to warn").setRequired(true))
            .addStringOption((opt) => opt.setName("reason").setDescription("Reason for warning").setRequired(true))
            .setDefaultMemberPermissions(PermissionFlagsBits.ModerateMembers),
        async execute(interaction, modService) {
            const targetUser = interaction.options.getUser("target", true);
            const reason = interaction.options.getString("reason", true);
            const targetMember = interaction.guild?.members.cache.get(targetUser.id);
            if (!targetMember) {
                return interaction.reply({ content: "That user is not currently in this server.", flags: MessageFlags.Ephemeral });
            }
            await interaction.deferReply();
            const result = await modService.warn(interaction.member, targetMember, reason);
            if (!result.success) {
                return interaction.editReply({ content: `❌ Warning failed: ${result.error}` });
            }
            return interaction.editReply({
                content: `⚠️ Warning issued to **${targetUser.tag}** (Total Strikes: ${result.warningCount}).\n**Reason:** ${reason}`,
            });
        },
    },
    // 5. /cases command
    {
        data: new SlashCommandBuilder()
            .setName("cases")
            .setDescription("View moderation infraction history for a user")
            .addUserOption((opt) => opt.setName("target").setDescription("Member to inspect").setRequired(true))
            .setDefaultMemberPermissions(PermissionFlagsBits.ModerateMembers),
        async execute(interaction, modService) {
            const targetUser = interaction.options.getUser("target", true);
            const cases = modService.getUserCases(interaction.guildId, targetUser.id);
            if (cases.length === 0) {
                return interaction.reply({
                    content: `No recorded moderation infractions for **${targetUser.tag}**. Clean record!`,
                    flags: MessageFlags.Ephemeral,
                });
            }
            const embed = new EmbedBuilder()
                .setTitle(`📜 Infraction History for ${targetUser.tag}`)
                .setColor(0x5865f2)
                .setDescription(`Found **${cases.length}** recorded case(s) in this server:`)
                .setThumbnail(targetUser.displayAvatarURL());
            cases.slice(-5).forEach((c) => {
                const date = new Date(c.timestamp).toLocaleDateString();
                embed.addFields({
                    name: `[${c.caseId}] ${c.action} • ${date}`,
                    value: `**Mod:** ${c.moderatorTag}\n**Reason:** ${c.reason}`,
                });
            });
            return interaction.reply({ embeds: [embed], flags: MessageFlags.Ephemeral });
        },
    },
];

/**
 * /setup Command
 * Interactive Server Onboarding Wizard with Discord Role Select Menus and Auto Log Channel Creation
 */
import { SlashCommandBuilder, PermissionFlagsBits, EmbedBuilder, ComponentType, MessageFlags, } from "discord.js";
export const setupCommand = {
    data: new SlashCommandBuilder()
        .setName("setup")
        .setDescription("Configure AegisMod roles and initialize the dedicated #mod-logs audit channel")
        .setDefaultMemberPermissions(PermissionFlagsBits.Administrator),
    async execute(interaction, roleService, loggingService, syncCommands) {
        if (!interaction.guild) {
            return interaction.reply({
                content: "This command can only be run inside a Discord server.",
                flags: MessageFlags.Ephemeral,
            });
        }
        await interaction.deferReply({ flags: MessageFlags.Ephemeral });
        // 1. Generate Interactive Role Select Menus
        const selectRows = roleService.createSetupRoleSelects(interaction.guild.id);
        const setupEmbed = new EmbedBuilder()
            .setTitle("🛡️ AegisMod Server Setup Wizard")
            .setDescription("Welcome to **AegisMod**! Please configure your server's role hierarchy below. " +
            "These roles will control command permissions and access to the dedicated audit log channel.")
            .setColor(0x5865f2)
            .addFields({
            name: "1. Owner / Executive Role",
            value: "Bypasses all moderation checks and has full emergency override.",
        }, {
            name: "2. Administrator Roles",
            value: "Can run `/setup`, `/cases`, and manage bot settings.",
        }, {
            name: "3. Moderator Roles",
            value: "Can execute `/ban`, `/kick`, `/mute`, `/warn`, and read `#mod-logs`.",
        }, {
            name: "4. Dedicated Audit Log Channel",
            value: "The bot will automatically create or bind `#mod-logs` visible only to staff.",
        })
            .setFooter({ text: "Select options below within 5 minutes to complete setup." });
        const message = await interaction.editReply({
            embeds: [setupEmbed],
            components: selectRows,
        });
        // Handle interactive selections
        let ownerRole = null;
        let adminRoles = [];
        let modRoles = [];
        const collector = message.createMessageComponentCollector({
            componentType: ComponentType.RoleSelect,
            time: 5 * 60 * 1000,
        });
        collector.on("collect", async (menuInteraction) => {
            if (menuInteraction.user.id !== interaction.user.id) {
                return menuInteraction.reply({
                    content: "Only the administrator who invoked /setup can configure roles.",
                    flags: MessageFlags.Ephemeral,
                });
            }
            const customId = menuInteraction.customId;
            const selected = menuInteraction.values;
            if (customId.includes(":owner:")) {
                ownerRole = selected[0] || null;
            }
            else if (customId.includes(":admin:")) {
                adminRoles = selected;
            }
            else if (customId.includes(":mod:")) {
                modRoles = selected;
            }
            // Save role mapping
            roleService.saveGuildRoles(interaction.guildId, ownerRole, adminRoles, modRoles);
            // Dynamically unlock and register moderation commands in this server
            if (syncCommands) {
                await syncCommands(interaction.guildId, true);
            }
            // Auto-create or ensure dedicated #mod-logs channel
            const staffRoles = [...adminRoles, ...modRoles];
            if (ownerRole)
                staffRoles.push(ownerRole);
            const logChannel = await loggingService.ensureLogChannel(interaction.guild, staffRoles);
            const updatedEmbed = new EmbedBuilder()
                .setTitle("✅ AegisMod Configuration Updated")
                .setColor(0x57f287)
                .setDescription("Your role configuration has been updated!")
                .addFields({
                name: "👑 Owner Role",
                value: ownerRole ? `<@&${ownerRole}>` : "*None selected*",
                inline: true,
            }, {
                name: "⚙️ Admin Roles",
                value: adminRoles.length ? adminRoles.map((r) => `<@&${r}>`).join(", ") : "*None selected*",
                inline: true,
            }, {
                name: "🛡️ Moderator Roles",
                value: modRoles.length ? modRoles.map((r) => `<@&${r}>`).join(", ") : "*None selected*",
                inline: true,
            }, {
                name: "📋 Dedicated Log Channel",
                value: `<#${logChannel.id}> (Auto-created with strict permissions)`,
                inline: false,
            })
                .setFooter({ text: "AegisMod is now monitoring messages for teenage safety." });
            await menuInteraction.update({
                embeds: [updatedEmbed],
                components: selectRows,
            });
        });
        collector.on("end", async () => {
            // Disable components after timeout
            await interaction.editReply({ components: [] }).catch(() => null);
        });
    },
};

/**
 * /testmod Slash Command
 * Diagnostic tool for server administrators and moderators
 * Simulates the full AegisMod moderation pipeline on a test message
 * without executing destructive actions or punishing the caller.
 */
import { SlashCommandBuilder, PermissionFlagsBits, EmbedBuilder, MessageFlags, } from "discord.js";
import { PolicyEngine } from "../services/policyEngine.js";
export const testModCommand = {
    data: new SlashCommandBuilder()
        .setName("testmod")
        .setDescription("Simulate AegisMod AutoMod & AI moderation on a sample message (Safe preview)")
        .setDefaultMemberPermissions(PermissionFlagsBits.ManageMessages)
        .addStringOption((opt) => opt
        .setName("content")
        .setDescription("The message text to evaluate through the moderation pipeline")
        .setRequired(true)),
    async execute(interaction, autoModService, triageService, geminiService) {
        if (!interaction.guild) {
            return interaction.reply({ content: "This command can only be run in a server.", flags: MessageFlags.Ephemeral });
        }
        await interaction.deferReply({ flags: MessageFlags.Ephemeral });
        const content = interaction.options.getString("content", true);
        const authorTag = interaction.user.tag;
        const guildName = interaction.guild.name;
        const startTime = Date.now();
        // 1. AutoMod Check
        const autoMod = autoModService.checkContent(content, interaction.user.id, interaction.guild.id, 0);
        // 2. Triage Check
        const triage = triageService.evaluate(content);
        // 3. AI Evaluation
        let aiResult = null;
        let pipelineSource = "AI (Gemini 3.8 Flash)";
        let rawClassification;
        if (autoMod.triggered) {
            pipelineSource = `Standard AutoMod (${autoMod.ruleName})`;
            rawClassification = {
                flagged: true,
                category: autoMod.category || "SEVERE_PROFANITY_OR_ABUSE",
                severity: autoMod.severity || "MEDIUM",
                confidence: 1.0,
                reason: autoMod.reason || "AutoMod local trigger",
                highlightedPhrases: autoMod.matchedContent ? [autoMod.matchedContent] : [],
                ageAppropriateNotes: "Deterministic standard AutoMod check.",
                tokensUsed: 0,
            };
        }
        else if (!triage.shouldCallGemini && triage.localVerdict) {
            pipelineSource = "Triage Filter (Local Heuristic)";
            rawClassification = {
                flagged: triage.localVerdict.flagged,
                category: triage.localVerdict.category,
                severity: triage.localVerdict.severity,
                confidence: 0.99,
                reason: triage.localVerdict.reason,
                highlightedPhrases: [],
                ageAppropriateNotes: "Triage evaluation.",
                tokensUsed: 0,
            };
        }
        else {
            aiResult = await geminiService.analyzeMessage(content, authorTag);
            pipelineSource = aiResult.isApiErrorFallback ? "AI Fallback (Heuristics)" : "Gemini 3.8 Flash";
            rawClassification = {
                flagged: aiResult.flagged,
                category: aiResult.category,
                severity: aiResult.severity,
                confidence: aiResult.confidence,
                reason: aiResult.reason,
                highlightedPhrases: aiResult.highlightedPhrases,
                ageAppropriateNotes: aiResult.ageAppropriateNotes,
                tokensUsed: aiResult.tokensUsed,
            };
        }
        // 4. Policy Engine
        const validated = PolicyEngine.validateClassification(rawClassification);
        const decision = PolicyEngine.evaluatePolicy(validated, guildName);
        const elapsedMs = Date.now() - startTime;
        // Build Response Embed
        const embed = new EmbedBuilder()
            .setTitle("🧪 AegisMod Pipeline Diagnostic Test")
            .setColor(validated.flagged ? 0xed4245 : 0x57f287)
            .setDescription(`**Input Message:**\n> "${content.slice(0, 300)}"`)
            .addFields({
            name: "Pipeline Resolution",
            value: `**Source:** ${pipelineSource}\n**Execution Time:** ${elapsedMs}ms\n**Tokens Consumed:** ${validated.tokensUsed || 0}`,
            inline: true,
        }, {
            name: "Classification Verdict",
            value: `**Flagged:** ${validated.flagged ? "🚨 YES" : "✅ NO"}\n**Category:** \`${validated.category}\`\n**Severity:** \`${validated.severity}\`\n**Confidence:** ${Math.round(validated.confidence * 100)}%`,
            inline: true,
        }, {
            name: "Policy Decision",
            value: `**Action:** \`${decision.action}\`\n**Executed Code:** \`${decision.executedActionDescription}\`\n**Staff Ping Required:** ${decision.requiresStaffNotification ? "🔔 YES" : "NO"}`,
            inline: false,
        }, {
            name: "Reasoning & Notes",
            value: validated.reason,
            inline: false,
        })
            .setFooter({ text: "This is a safe diagnostic test. No moderation actions were taken." })
            .setTimestamp();
        return interaction.editReply({ embeds: [embed] });
    },
};

/**
 * messageCreate Event Listener
 * Core Real-Time AI Content Moderation Pipeline
 */
import { PolicyEngine } from "../services/policyEngine.js";
export async function handleMessageCreate(message, triageService, geminiService, loggingService, roleService, autoModService) {
    // 1. Guard clauses: Ignore bots, DMs, or empty messages
    if (message.author.bot || !message.guild || !message.content?.trim()) {
        return;
    }
    // 2. Staff exemption check
    const member = message.member || (await message.guild.members.fetch(message.author.id).catch(() => null));
    if (member && roleService.isStaffOrExempt(member)) {
        return;
    }
    try {
        const rawContent = message.content;
        // 3. Step 1: Standard AutoMod Heuristic & Security Layer (Deterministic local protection)
        let rawClassification;
        if (autoModService) {
            const autoModResult = autoModService.checkMessage(message);
            if (autoModResult.triggered) {
                rawClassification = {
                    flagged: true,
                    category: autoModResult.category || "SEVERE_PROFANITY_OR_ABUSE",
                    severity: autoModResult.severity || "MEDIUM",
                    confidence: 1.0,
                    reason: autoModResult.reason || "Triggered local AutoMod rule",
                    highlightedPhrases: autoModResult.matchedContent ? [autoModResult.matchedContent] : [],
                    ageAppropriateNotes: "Deterministic Standard AutoMod filter.",
                    tokensUsed: 0,
                };
            }
        }
        // Step 2: Triage & Token Efficiency Filter (if not already flagged by AutoMod)
        if (!rawClassification) {
            const triage = triageService.evaluate(rawContent);
            if (!triage.shouldCallGemini && triage.localVerdict) {
                // Handled entirely by Tier-1 or Tier-2 local triage
                rawClassification = {
                    flagged: triage.localVerdict.flagged,
                    category: triage.localVerdict.category,
                    severity: triage.localVerdict.severity,
                    confidence: 0.95,
                    reason: triage.localVerdict.reason,
                    highlightedPhrases: [],
                    ageAppropriateNotes: "Local triage evaluation.",
                    tokensUsed: 0,
                };
            }
            else {
                // Step 3: Pass to Gemini 3.8 Flash for deep contextual analysis
                const aiResult = await geminiService.analyzeMessage(rawContent, message.author.tag);
                rawClassification = {
                    flagged: aiResult.flagged,
                    category: aiResult.category,
                    severity: aiResult.severity,
                    confidence: aiResult.confidence,
                    reason: aiResult.reason,
                    highlightedPhrases: aiResult.highlightedPhrases,
                    ageAppropriateNotes: aiResult.ageAppropriateNotes,
                    tokensUsed: aiResult.tokensUsed,
                };
                // Cache the verdict for future duplicate messages if not an API error
                if (!aiResult.isApiErrorFallback) {
                    triageService.cacheVerdict(rawContent, {
                        flagged: aiResult.flagged,
                        category: aiResult.category,
                        severity: aiResult.severity,
                        recommendedAction: aiResult.recommendedAction,
                        reason: `Cached from Gemini: ${aiResult.reason}`,
                    });
                }
            }
        }
        // 4. ARCHITECTURAL MANDATE: Validate classification & evaluate via PolicyEngine
        // Pipeline: User message -> AI classifier -> validated classification -> policy engine -> Discord action
        const validatedClassification = PolicyEngine.validateClassification(rawClassification);
        const policyDecision = PolicyEngine.evaluatePolicy(validatedClassification, message.guild.name);
        // 5. Action Execution if Policy dictates an action other than ALLOW
        if (policyDecision.action !== "ALLOW") {
            // Direct message notification to the user if policy dictates
            if (policyDecision.notifyUser && policyDecision.userMessage) {
                await message.author.send({ content: policyDecision.userMessage }).catch(() => null);
            }
            switch (policyDecision.action) {
                case "DELETE":
                    await message.delete().catch(() => null);
                    break;
                case "WARN":
                    // User already notified via DM if enabled
                    break;
                case "TIMEOUT_1H":
                case "TIMEOUT_24H": {
                    const duration = policyDecision.durationMs || (policyDecision.action === "TIMEOUT_1H" ? 3600000 : 86400000);
                    await message.delete().catch(() => null);
                    if (member && member.moderatable) {
                        await member.timeout(duration, `AegisMod Policy: [${policyDecision.category}] ${policyDecision.reason}`).catch(() => null);
                    }
                    break;
                }
                case "BAN": {
                    await message.delete().catch(() => null);
                    if (member && member.bannable) {
                        await member.ban({ reason: `AegisMod Policy: [${policyDecision.category}] ${policyDecision.reason}` }).catch(() => null);
                    }
                    break;
                }
            }
            // 6. Send rich audit record to dedicated #mod-logs channel with optional staff alert
            const guildRoles = roleService.getGuildRoles(message.guild.id);
            const staffRoleIds = guildRoles ? [...guildRoles.adminRoleIds, ...guildRoles.moderatorRoleIds] : [];
            await loggingService.logAIAction(message, {
                flagged: validatedClassification.flagged,
                category: validatedClassification.category,
                severity: validatedClassification.severity,
                recommendedAction: policyDecision.action,
                confidence: validatedClassification.confidence,
                reason: validatedClassification.reason,
                highlightedPhrases: validatedClassification.highlightedPhrases,
                ageAppropriateNotes: validatedClassification.ageAppropriateNotes || "",
                tokensUsed: validatedClassification.tokensUsed || 0,
            }, policyDecision.executedActionDescription, {
                requiresStaffNotification: policyDecision.requiresStaffNotification,
                staffRoleIds,
            });
        }
    }
    catch (err) {
        console.error("[handleMessageCreate] Unexpected moderation pipeline error:", err);
    }
}

/**
 * messageDelete Event Listener
 * Catches message deletions and writes comprehensive audit logs to #mod-logs.
 */
export async function handleMessageDelete(message, loggingService) {
    if (message.partial) {
        // If not cached, we cannot recover content but can still log deletion if desirable
        return;
    }
    const fullMessage = message;
    if (fullMessage.author?.bot || !fullMessage.guild)
        return;
    await loggingService.logMessageDelete(fullMessage);
}

/**
 * messageUpdate Event Listener
 * Detects edited messages, checks if edited text bypasses moderation, and logs the diff to #mod-logs.
 */
import { handleMessageCreate } from "./messageCreate.js";
export async function handleMessageUpdate(oldMessage, newMessage, loggingService, triageService, geminiService, roleService, autoModService) {
    // If partial, try to fetch full message
    if (newMessage.partial) {
        try {
            await newMessage.fetch();
        }
        catch {
            return;
        }
    }
    const fullNewMessage = newMessage;
    const fullOldMessage = (oldMessage.partial ? null : oldMessage);
    if (fullNewMessage.author?.bot || !fullNewMessage.guild)
        return;
    if (fullOldMessage && fullOldMessage.content === fullNewMessage.content)
        return;
    // 1. Log the edit audit trail to #mod-logs
    if (fullOldMessage) {
        await loggingService.logMessageEdit(fullOldMessage, fullNewMessage);
    }
    // 2. Re-scan edited message through moderation pipeline to prevent bypasses
    await handleMessageCreate(fullNewMessage, triageService, geminiService, loggingService, roleService, autoModService);
}

