                tokensUsed: 0,
                isApiErrorFallback: true,
            };
        }
        return {
            flagged: false,
            category: "NONE",
            severity: "NONE",
            recommendedAction: "ALLOW",
            confidence: 0.5,
            reason: baseReason,
            highlightedPhrases: [],
