    }
}

/**
 * Logging Service
 * Manages the dedicated #mod-logs channel and formats comprehensive audit records
 * for message deletions, edits, AI auto-mod flags, and traditional moderation commands.
 */
import { ChannelType, EmbedBuilder, PermissionFlagsBits, } from "discord.js";
export class LoggingService {
    logChannelCache = new Map(); // guildId -> channelId
    /**
     * Ensures a dedicated, secure #mod-logs channel exists with strict permissions.
     */
    async ensureLogChannel(guild, staffRoleIds = []) {
        const cachedId = this.logChannelCache.get(guild.id);
        if (cachedId) {
            const channel = guild.channels.cache.get(cachedId);
            if (channel)
                return channel;
        }
        // Look for existing channel named mod-logs or moderation-logs
        const existing = guild.channels.cache.find((c) => c.type === ChannelType.GuildText &&
            (c.name === "mod-logs" || c.name === "aegis-logs" || c.name === "moderation-logs"));
        if (existing) {
            this.logChannelCache.set(guild.id, existing.id);
            return existing;
        }
        // Create permission overwrites: Hide from @everyone, allow bot and staff roles
        const permissionOverwrites = [
            {
                id: guild.roles.everyone.id,
                deny: [PermissionFlagsBits.ViewChannel, PermissionFlagsBits.SendMessages],
            },
            {
                id: guild.client.user.id,
                allow: [
                    PermissionFlagsBits.ViewChannel,
                    PermissionFlagsBits.SendMessages,
                    PermissionFlagsBits.EmbedLinks,
                    PermissionFlagsBits.AttachFiles,
                    PermissionFlagsBits.ReadMessageHistory,
                ],
            },
        ];
        for (const roleId of staffRoleIds) {
            if (roleId) {
                permissionOverwrites.push({
                    id: roleId,
                    allow: [
                        PermissionFlagsBits.ViewChannel,
                        PermissionFlagsBits.ReadMessageHistory,
                    ],
                    deny: [PermissionFlagsBits.SendMessages],
                });
            }
        }
        // Auto-create channel
        const newChannel = await guild.channels.create({
            name: "mod-logs",
            type: ChannelType.GuildText,
            topic: "AegisMod Audit Log — Automated AI moderation actions, deletions, edits & staff records.",
            permissionOverwrites,
            reason: "Automatic setup of AegisMod dedicated moderation logging channel",
        });
        this.logChannelCache.set(guild.id, newChannel.id);
        // Post welcome embed
        const welcomeEmbed = new EmbedBuilder()
            .setTitle("🛡️ AegisMod Logging Channel Initialized")
            .setDescription("This channel has been automatically created and configured. All moderation activities, deleted messages, edited messages, and AI detections will be logged here.")
            .setColor(0x5865f2)
            .addFields({ name: "Channel Privacy", value: "Locked: `@everyone` cannot view this channel.", inline: true }, { name: "Target Community", value: "Strict Teen Safety (~16 y/o standards)", inline: true })
            .setTimestamp();
        await newChannel.send({ embeds: [welcomeEmbed] });
        return newChannel;
    }
    /**
     * Dispatches log for an AI-driven automated moderation action
     */
    async logAIAction(message, aiResult, actionTaken, options) {
        if (!message.guild)
            return;
        const logChannel = await this.ensureLogChannel(message.guild);
        const embed = new EmbedBuilder()
            .setTitle(`🤖 AI Moderation Action: ${actionTaken}`)
            .setColor(aiResult.severity === "CRITICAL"
            ? 0xed4245
            : aiResult.severity === "HIGH"
                ? 0xe67e22
                : 0xf1c40f)
            .setAuthor({
            name: `${message.author.tag} (${message.author.id})`,
            iconURL: message.author.displayAvatarURL(),
        })
            .addFields({ name: "Offending Content", value: `\`\`\`${message.content.slice(0, 1000)}\`\`\`` }, { name: "Category", value: `\`${aiResult.category}\``, inline: true }, { name: "Severity", value: `\`${aiResult.severity}\``, inline: true }, { name: "Confidence", value: `${Math.round(aiResult.confidence * 100)}%`, inline: true }, { name: "Channel", value: `<#${message.channel.id}>`, inline: true }, { name: "Tokens Used", value: `${aiResult.tokensUsed} tokens`, inline: true }, { name: "AI Reason", value: aiResult.reason })
            .setFooter({ text: "AegisMod AI Engine • Powered by Gemini 3.8 Flash" })
            .setTimestamp();
        if (aiResult.highlightedPhrases.length > 0) {
            embed.addFields({
                name: "Flagged Substrings",
                value: aiResult.highlightedPhrases.map((p) => `\`${p}\``).join(", "),
            });
        }
        let contentAlert = undefined;
        if (options?.requiresStaffNotification) {
            const pingText = options.staffRoleIds && options.staffRoleIds.length > 0
                ? options.staffRoleIds.map((r) => `<@&${r}>`).join(" ")
                : "@here";
            contentAlert = `🚨 **CRITICAL YOUTH SAFETY ALERT:** Immediate staff review required! ${pingText}`;
        }
        await logChannel.send({
            content: contentAlert,
            embeds: [embed],
        });
    }
    /**
     * Dispatches log for a deleted message
     */
    async logMessageDelete(message) {
        if (!message.guild || message.author.bot)
            return;
        const logChannel = await this.ensureLogChannel(message.guild);
        const embed = new EmbedBuilder()
            .setTitle("🗑️ Message Deleted")
            .setColor(0xe74c3c)
            .setAuthor({
            name: `${message.author.tag} (${message.author.id})`,
            iconURL: message.author.displayAvatarURL(),
        })
            .addFields({ name: "Author", value: `<@${message.author.id}>`, inline: true }, { name: "Channel", value: `<#${message.channel.id}>`, inline: true }, {
            name: "Original Content",
            value: message.content ? `\`\`\`${message.content.slice(0, 1000)}\`\`\`` : "*[No text content or embed/attachment]*",
        })
            .setFooter({ text: `Message ID: ${message.id}` })
            .setTimestamp();
        await logChannel.send({ embeds: [embed] });
    }
    /**
     * Dispatches log for an edited message
     */
    async logMessageEdit(oldMessage, newMessage) {
        if (!oldMessage.guild || oldMessage.author.bot)
            return;
        if (oldMessage.content === newMessage.content)
            return; // ignore embed loads
        const logChannel = await this.ensureLogChannel(oldMessage.guild);
        const embed = new EmbedBuilder()
            .setTitle("✏️ Message Edited")
            .setColor(0xf39c12)
            .setAuthor({
            name: `${oldMessage.author.tag} (${oldMessage.author.id})`,
            iconURL: oldMessage.author.displayAvatarURL(),
        })
            .addFields({ name: "Author", value: `<@${oldMessage.author.id}>`, inline: true }, { name: "Channel", value: `<#${oldMessage.channel.id}>`, inline: true }, { name: "Jump To Message", value: `[Click Here](${newMessage.url})`, inline: true }, { name: "Before", value: `\`\`\`${(oldMessage.content || "*[empty]*").slice(0, 500)}\`\`\`` }, { name: "After", value: `\`\`\`${(newMessage.content || "*[empty]*").slice(0, 500)}\`\`\`` })
            .setFooter({ text: `Message ID: ${newMessage.id}` })
            .setTimestamp();
        await logChannel.send({ embeds: [embed] });
    }
    /**
     * Dispatches log for traditional moderation commands (ban, kick, mute, warn)
     */
    async logTraditionalModAction(guild, target, moderator, action, reason, durationFormatted) {
        const logChannel = await this.ensureLogChannel(guild);
        const colors = {
            BAN: 0xed4245,
            KICK: 0xe67e22,
            MUTE: 0x9b59b6,
            WARN: 0xf1c40f,
            UNMUTE: 0x2ecc71,
        };
        const embed = new EmbedBuilder()
            .setTitle(`🔨 Moderation Action: ${action}`)
            .setColor(colors[action] || 0x95a5a6)
            .setThumbnail(target.displayAvatarURL())
            .addFields({ name: "Target User", value: `${target.tag} (<@${target.id}>)`, inline: true }, { name: "Moderator", value: `${moderator.tag} (<@${moderator.id}>)`, inline: true }, { name: "Reason", value: reason || "No reason specified" })
            .setTimestamp();
        if (durationFormatted) {
            embed.addFields({ name: "Duration", value: durationFormatted, inline: true });
        }
        await logChannel.send({ embeds: [embed] });
    }
}

/**
 * Moderation Policy Engine
 * Enforces strictly deterministic server-side mapping between AI/Triage classifications
 * and concrete Discord moderation actions.
 *
 * ARCHITECTURAL MANDATE:
 * User message -> AI/Triage classifier -> validated classification -> Policy Engine -> Discord action.
 * Never allows raw AI text to trigger arbitrary Discord actions.
 */
export class PolicyEngine {
    /**
     * Sanitizes and validates raw classification inputs, rejecting unknown categories or severities.
     */
    static validateClassification(raw) {
        const validCategories = new Set([
            "NONE",
            "CYBERBULLYING",
            "HARASSMENT",
            "SEXUAL_GROOMING_OR_PREDATORY",
            "SELF_HARM",
            "HATE_SPEECH",
            "SEVERE_PROFANITY_OR_ABUSE",
            "DOXXING_OR_PII",
            "PROMPT_INJECTION_OR_JAILBREAK",
            "INVITE_LINK_SPAM",
            "PHISHING_OR_SCAM",
            "MASS_MENTION_SPAM",
            "FLOOD_OR_SPAM",
            "EXCESSIVE_CAPS",
            "GLITCH_OR_ZALGO",
        ]);
        const validSeverities = new Set(["NONE", "LOW", "MEDIUM", "HIGH", "CRITICAL"]);
        const category = validCategories.has(raw?.category)
            ? raw.category
            : "NONE";
        const severity = validSeverities.has(raw?.severity)
            ? raw.severity
            : "NONE";
        const flagged = Boolean(raw?.flagged) && category !== "NONE" && severity !== "NONE";
        const confidence = typeof raw?.confidence === "number" ? Math.max(0, Math.min(1, raw.confidence)) : 0.8;
        const reason = typeof raw?.reason === "string" && raw.reason.trim() ? raw.reason.trim() : "Automated policy evaluation.";
        const highlightedPhrases = Array.isArray(raw?.highlightedPhrases)
            ? raw.highlightedPhrases.filter((p) => typeof p === "string" && p.length > 0)
            : [];
        return {
            flagged,
            category,
            severity,
            confidence,
            reason,
            highlightedPhrases,
            ageAppropriateNotes: typeof raw?.ageAppropriateNotes === "string" ? raw.ageAppropriateNotes : undefined,
            tokensUsed: typeof raw?.tokensUsed === "number" ? raw.tokensUsed : 0,
        };
    }
    /**
     * Evaluates a validated classification against strict teen safety escalation policies.
     * Deterministic matrix ensures no arbitrary actions can be executed.
     */
    static evaluatePolicy(classification, guildName = "the server") {
        if (!classification.flagged || classification.category === "NONE" || classification.severity === "NONE") {
            return {
                action: "ALLOW",
                executedActionDescription: "CLEAN_PASS",
                category: "NONE",
                severity: "NONE",
                confidence: classification.confidence,
                reason: classification.reason,
                requiresStaffNotification: false,
                notifyUser: false,
            };
        }
        // 1. Zero-Tolerance Predatory Grooming -> IMMEDIATE BAN + STAFF PING
        if (classification.category === "SEXUAL_GROOMING_OR_PREDATORY") {
            return {
                action: "BAN",
                executedActionDescription: "BANNED_PREDATORY_GROOMING",
                category: classification.category,
                severity: "CRITICAL",
                confidence: classification.confidence,
                reason: classification.reason,
                requiresStaffNotification: true,
                notifyUser: true,
                userMessage: `🔨 You have been banned from **${guildName}** for severe violation of youth safety standards: ${classification.reason}`,
            };
        }
        // 2. Self-Harm & Suicide Encouragement -> Immediate 24h Timeout + Staff Ping
        if (classification.category === "SELF_HARM") {
            return {
                action: "TIMEOUT_24H",
                executedActionDescription: "DELETED_AND_TIMEOUT_24H_SELF_HARM",
                category: classification.category,
                severity: "CRITICAL",
                confidence: classification.confidence,
                reason: classification.reason,
                durationMs: 24 * 60 * 60 * 1000,
                requiresStaffNotification: true,
                notifyUser: true,
