            };
        }
        // 3. Doxxing & Minor PII Exposure -> Immediate 24h Timeout + Delete + Staff Ping
        if (classification.category === "DOXXING_OR_PII") {
            return {
                action: "TIMEOUT_24H",
                executedActionDescription: "DELETED_AND_TIMEOUT_24H_DOXXING",
                category: classification.category,
