            };
        }
        // 4. Hate Speech
        if (classification.category === "HATE_SPEECH") {
            const isCritical = classification.severity === "CRITICAL" || classification.severity === "HIGH";
            const action = isCritical ? "TIMEOUT_1H" : "DELETE";
            return {
                action,
                executedActionDescription: isCritical ? "DELETED_AND_TIMEOUT_1H_HATE_SPEECH" : "MESSAGE_DELETED_HATE_SPEECH",
                category: classification.category,
                severity: classification.severity,
                confidence: classification.confidence,
                reason: classification.reason,
                durationMs: isCritical ? 60 * 60 * 1000 : undefined,
                requiresStaffNotification: isCritical,
                notifyUser: true,
                userMessage: `⚠️ Your message was removed in **${guildName}** for violating anti-hate and community safety rules.`,
            };
        }
        // 5. Cyberbullying & Targeted Harassment
        if (classification.category === "CYBERBULLYING" || classification.category === "HARASSMENT") {
            if (classification.severity === "CRITICAL" || classification.severity === "HIGH") {
                return {
                    action: "TIMEOUT_1H",
                    executedActionDescription: "DELETED_AND_TIMEOUT_1H_HARASSMENT",
                    category: classification.category,
                    severity: classification.severity,
                    confidence: classification.confidence,
                    reason: classification.reason,
                    durationMs: 60 * 60 * 1000,
                    requiresStaffNotification: false,
                    notifyUser: true,
                    userMessage: `⚠️ You have been placed on a 1-hour timeout in **${guildName}** for targeted harassment or cyberbullying.`,
                };
            }
            return {
                action: "DELETE",
                executedActionDescription: "MESSAGE_DELETED_HARASSMENT",
                category: classification.category,
                severity: classification.severity,
                confidence: classification.confidence,
                reason: classification.reason,
                requiresStaffNotification: false,
                notifyUser: true,
                userMessage: `⚠️ Your message was removed in **${guildName}** for violating teen harassment policies: ${classification.reason}`,
            };
        }
        // 6. Severe Profanity or Abuse
        if (classification.category === "SEVERE_PROFANITY_OR_ABUSE") {
            if (classification.severity === "HIGH") {
                return {
                    action: "DELETE",
                    executedActionDescription: "MESSAGE_DELETED_PROFANITY",
                    category: classification.category,
                    severity: classification.severity,
                    confidence: classification.confidence,
                    reason: classification.reason,
                    requiresStaffNotification: false,
                    notifyUser: true,
                    userMessage: `⚠️ Your message was removed in **${guildName}** for excessive vulgarity or evasion.`,
                };
            }
            return {
                action: "WARN",
                executedActionDescription: "USER_WARNED_PROFANITY",
                category: classification.category,
                severity: "LOW",
                confidence: classification.confidence,
                reason: classification.reason,
                requiresStaffNotification: false,
                notifyUser: true,
                userMessage: `⚠️ Reminder: Please keep language civil and respectful in **${guildName}**.`,
            };
        }
        // 7. Prompt Injection / Jailbreak attempt
        if (classification.category === "PROMPT_INJECTION_OR_JAILBREAK") {
            return {
                action: "DELETE",
                executedActionDescription: "MESSAGE_DELETED_PROMPT_INJECTION",
                category: classification.category,
                severity: "HIGH",
                confidence: classification.confidence,
                reason: "Adversarial prompt injection attempt detected.",
                requiresStaffNotification: true,
                notifyUser: true,
                userMessage: `⚠️ System command bypass attempts are not permitted in **${guildName}**.`,
            };
        }
        // 8. AutoMod: Phishing & Malicious Scams -> 24h Timeout + Delete + Staff Ping
        if (classification.category === "PHISHING_OR_SCAM") {
            return {
                action: "TIMEOUT_24H",
                executedActionDescription: "DELETED_AND_TIMEOUT_24H_PHISHING",
                category: classification.category,
                severity: "CRITICAL",
                confidence: classification.confidence,
                reason: classification.reason,
                durationMs: 24 * 60 * 60 * 1000,
                requiresStaffNotification: true,
                notifyUser: true,
                userMessage: `⚠️ You have been placed on a 24-hour timeout in **${guildName}** for distributing suspected phishing or malicious links.`,
            };
        }
        // 9. AutoMod: Mass Mention Spam -> 1h Timeout + Delete + Staff Ping
        if (classification.category === "MASS_MENTION_SPAM") {
            return {
                action: "TIMEOUT_1H",
                executedActionDescription: "DELETED_AND_TIMEOUT_1H_MASS_MENTION",
                category: classification.category,
                severity: "HIGH",
                confidence: classification.confidence,
                reason: classification.reason,
                durationMs: 60 * 60 * 1000,
                requiresStaffNotification: true,
                notifyUser: true,
                userMessage: `⚠️ Your message was removed and you have been timed out for 1 hour in **${guildName}** for mass mention spam.`,
            };
        }
        // 10. AutoMod: Invite Link Spam -> Delete + Warning
        if (classification.category === "INVITE_LINK_SPAM") {
            return {
                action: "DELETE",
                executedActionDescription: "MESSAGE_DELETED_INVITE_LINK",
                category: classification.category,
                severity: "MEDIUM",
                confidence: classification.confidence,
                reason: classification.reason,
                requiresStaffNotification: false,
                notifyUser: true,
                userMessage: `⚠️ Unauthorized Discord server invite links are not permitted in **${guildName}**.`,
            };
        }
        // 11. AutoMod: Fast Spam / Flood -> Delete
        if (classification.category === "FLOOD_OR_SPAM") {
            return {
                action: "DELETE",
                executedActionDescription: "MESSAGE_DELETED_SPAM_FLOOD",
                category: classification.category,
                severity: "MEDIUM",
                confidence: classification.confidence,
                reason: classification.reason,
                requiresStaffNotification: false,
                notifyUser: true,
                userMessage: `⚠️ Please slow down! Rapid message flooding is prohibited in **${guildName}**.`,
            };
        }
        // 12. AutoMod: Excessive Caps & Zalgo -> Delete
        if (classification.category === "EXCESSIVE_CAPS" || classification.category === "GLITCH_OR_ZALGO") {
            return {
                action: "DELETE",
                executedActionDescription: classification.category === "EXCESSIVE_CAPS" ? "MESSAGE_DELETED_CAPS" : "MESSAGE_DELETED_ZALGO",
                category: classification.category,
                severity: classification.severity,
                confidence: classification.confidence,
                reason: classification.reason,
                requiresStaffNotification: false,
                notifyUser: true,
                userMessage: classification.category === "EXCESSIVE_CAPS"
                    ? `⚠️ Please avoid sending messages in all uppercase in **${guildName}**.`
                    : `⚠️ Messages containing glitch or excessive zalgo characters are not permitted in **${guildName}**.`,
            };
        }
        // Default Fallback: Warn
        return {
            action: "WARN",
            executedActionDescription: "USER_WARNED",
            category: classification.category,
            severity: classification.severity,
            confidence: classification.confidence,
            reason: classification.reason,
            requiresStaffNotification: false,
            notifyUser: false,
        };
    }
}

/**
 * Role Service
 * Handles interactive role setup (Owner, Admin, Moderator) using Discord RoleSelectMenuBuilder,
 * role hierarchy validations, permission checks, and guild configurations.
 */
import { ActionRowBuilder, RoleSelectMenuBuilder, PermissionFlagsBits, } from "discord.js";
import fs from "fs";
import path from "path";
export class RoleService {
    guildRoles = new Map();
    dataFilePath = path.join(process.cwd(), "guild_roles.json");
    writeQueue = Promise.resolve();
    constructor() {
        this.loadFromDisk();
    }
    async loadFromDisk() {
        try {
            if (fs.existsSync(this.dataFilePath)) {
                const raw = await fs.promises.readFile(this.dataFilePath, "utf8");
                const parsed = JSON.parse(raw);
                for (const key of Object.keys(parsed)) {
                    this.guildRoles.set(key, parsed[key]);
                }
            }
        }
        catch (err) {
            console.warn("[RoleService] Warning: Unable to parse guild_roles.json, falling back to memory store:", err);
        }
    }
    async persistToDisk() {
        // Chain writes to serialize async operations and avoid file corruption
        this.writeQueue = this.writeQueue
            .then(async () => {
            const obj = {};
            this.guildRoles.forEach((val, key) => {
                obj[key] = val;
            });
            const tempPath = `${this.dataFilePath}.tmp`;
            await fs.promises.writeFile(tempPath, JSON.stringify(obj, null, 2), "utf8");
            await fs.promises.rename(tempPath, this.dataFilePath);
        })
            .catch((err) => {
            console.error("[RoleService] Failed to persist role mappings to disk:", err);
        });
    }
    /**
     * Generates the Discord Role Select Menu components for server onboarding
     */
    createSetupRoleSelects(guildId) {
        // 1. Owner Role Select Menu
        const ownerSelect = new RoleSelectMenuBuilder()
            .setCustomId(`setup:role:owner:${guildId}`)
            .setPlaceholder("Select Server Owner / Executive Role")
            .setMinValues(1)
            .setMaxValues(1);
        // 2. Admin Roles Select Menu
        const adminSelect = new RoleSelectMenuBuilder()
            .setCustomId(`setup:role:admin:${guildId}`)
            .setPlaceholder("Select Administrator Roles (Full Control)")
            .setMinValues(1)
            .setMaxValues(5);
        // 3. Moderator Roles Select Menu
        const modSelect = new RoleSelectMenuBuilder()
            .setCustomId(`setup:role:mod:${guildId}`)
            .setPlaceholder("Select Moderator Roles (Kick, Ban, Mute, Warn)")
            .setMinValues(1)
            .setMaxValues(10);
        return [
            new ActionRowBuilder().addComponents(ownerSelect),
            new ActionRowBuilder().addComponents(adminSelect),
            new ActionRowBuilder().addComponents(modSelect),
        ];
    }
    /**
     * Saves role mappings configured via Discord Select Menus
     */
    saveGuildRoles(guildId, ownerRoleId, adminRoleIds, moderatorRoleIds) {
        const mapping = {
            guildId,
            ownerRoleId,
            adminRoleIds,
            moderatorRoleIds,
            configuredAt: Date.now(),
        };
        this.guildRoles.set(guildId, mapping);
        this.persistToDisk();
        return mapping;
    }
    isGuildConfigured(guildId) {
        return this.guildRoles.has(guildId);
    }
    getGuildRoles(guildId) {
        return this.guildRoles.get(guildId);
    }
    /**
     * Checks if member is exempt from moderation (Staff, Bot, or Owner)
     */
    isStaffOrExempt(member) {
        if (member.user.bot)
            return true;
        if (member.id === member.guild.ownerId)
            return true;
        if (member.permissions.has(PermissionFlagsBits.Administrator))
            return true;
        const config = this.getGuildRoles(member.guild.id);
        if (!config)
            return false;
        // Check owner role
        if (config.ownerRoleId && member.roles.cache.has(config.ownerRoleId)) {
            return true;
        }
        // Check admin roles
        if (config.adminRoleIds.some((id) => member.roles.cache.has(id))) {
            return true;
        }
        // Check moderator roles
        if (config.moderatorRoleIds.some((id) => member.roles.cache.has(id))) {
            return true;
        }
        return false;
    }
    /**
     * Validates if executor can moderate the target based on Discord hierarchy
     */
    canModerateMember(executor, target, action) {
        // Cannot moderate server owner
        if (target.id === target.guild.ownerId) {
            return { allowed: false, reason: "You cannot moderate the Server Owner." };
        }
        // Cannot moderate oneself
        if (executor.id === target.id) {
            return { allowed: false, reason: "You cannot take moderation action on yourself." };
        }
        // Guild Owner can moderate anyone
        if (executor.id === executor.guild.ownerId) {
            return { allowed: true };
        }
        // Role hierarchy check
        if (executor.roles.highest.position <= target.roles.highest.position) {
            return {
                allowed: false,
                reason: "Your highest role is lower or equal to the target's highest role in Discord's hierarchy.",
            };
        }
        // Bot permission check
        const botMember = target.guild.members.me;
        if (botMember && botMember.roles.highest.position <= target.roles.highest.position) {
            return {
                allowed: false,
                reason: "The Bot's role is lower than the target member's role and cannot perform this action.",
            };
        }
        return { allowed: true };
    }
}

/**
 * Traditional Moderation Service
 * Handles manual moderation commands: /ban, /kick, /mute (timeout), /warn, and infraction tracking.
 */
import fs from "fs";
import path from "path";
export class TraditionalModService {
    loggingService;
    roleService;
    infractions = new Map(); // guildId:userId -> InfractionRecord[]
    caseCounter = 1000;
    infractionsFilePath = path.join(process.cwd(), "infractions.json");
    writeQueue = Promise.resolve();
    constructor(loggingService, roleService) {
        this.loggingService = loggingService;
        this.roleService = roleService;
        this.loadFromDisk();
    }
    async loadFromDisk() {
        try {
            if (fs.existsSync(this.infractionsFilePath)) {
                const raw = await fs.promises.readFile(this.infractionsFilePath, "utf8");
                const parsed = JSON.parse(raw);
                if (parsed.infractions && typeof parsed.infractions === "object") {
                    for (const key of Object.keys(parsed.infractions)) {
                        this.infractions.set(key, parsed.infractions[key]);
                    }
                }
                if (typeof parsed.caseCounter === "number") {
                    this.caseCounter = parsed.caseCounter;
                }
            }
        }
        catch (err) {
            console.warn("[TraditionalModService] Unable to load infractions.json, starting fresh:", err);
        }
    }
    async persistToDisk() {
        this.writeQueue = this.writeQueue
            .then(async () => {
            const obj = {};
            this.infractions.forEach((val, key) => {
                obj[key] = val;
            });
            const data = {
                caseCounter: this.caseCounter,
                infractions: obj,
            };
            const tempPath = `${this.infractionsFilePath}.tmp`;
            await fs.promises.writeFile(tempPath, JSON.stringify(data, null, 2), "utf8");
            await fs.promises.rename(tempPath, this.infractionsFilePath);
        })
            .catch((err) => {
            console.error("[TraditionalModService] Failed to persist infractions to disk:", err);
        });
    }
    /**
     * Bans a member from the guild with optional message pruning
     */
    async ban(moderator, target, reason, deleteMessageDays = 1) {
        const check = this.roleService.canModerateMember(moderator, target, "BAN");
        if (!check.allowed)
            return { success: false, error: check.reason };
        try {
            // Send DM notification to user before banning
            await target.send({
                content: `You have been banned from **${target.guild.name}**.\n**Reason:** ${reason}`,
            }).catch(() => null);
            await target.ban({
                reason: `${moderator.user.tag}: ${reason}`,
                deleteMessageSeconds: deleteMessageDays * 86400,
            });
            this.recordInfraction({
                guildId: target.guild.id,
                targetId: target.id,
                targetTag: target.user.tag,
                moderatorId: moderator.id,
                moderatorTag: moderator.user.tag,
                action: "BAN",
                reason,
                timestamp: Date.now(),
            });
            await this.loggingService.logTraditionalModAction(target.guild, target.user, moderator.user, "BAN", reason);
            return { success: true };
        }
        catch (err) {
            return { success: false, error: err.message };
        }
    }
    /**
     * Kicks a member from the guild
     */
    async kick(moderator, target, reason) {
        const check = this.roleService.canModerateMember(moderator, target, "KICK");
        if (!check.allowed)
            return { success: false, error: check.reason };
        try {
            await target.send({
                content: `You have been kicked from **${target.guild.name}**.\n**Reason:** ${reason}`,
            }).catch(() => null);
            await target.kick(`${moderator.user.tag}: ${reason}`);
            this.recordInfraction({
                guildId: target.guild.id,
                targetId: target.id,
                targetTag: target.user.tag,
                moderatorId: moderator.id,
                moderatorTag: moderator.user.tag,
                action: "KICK",
                reason,
                timestamp: Date.now(),
            });
            await this.loggingService.logTraditionalModAction(target.guild, target.user, moderator.user, "KICK", reason);
            return { success: true };
        }
        catch (err) {
            return { success: false, error: err.message };
        }
    }
    /**
     * Mutes (times out) a member using Discord's native timeout feature
     */
    async mute(moderator, target, durationMs, reason) {
        const check = this.roleService.canModerateMember(moderator, target, "MUTE");
        if (!check.allowed)
            return { success: false, error: check.reason };
        // Discord limits timeouts to 28 days
        const maxDuration = 28 * 24 * 60 * 60 * 1000;
        if (durationMs > maxDuration) {
            return { success: false, error: "Timeout duration cannot exceed 28 days." };
        }
        try {
            await target.timeout(durationMs, `${moderator.user.tag}: ${reason}`);
            const formattedDuration = this.formatDuration(durationMs);
            await target.send({
                content: `You have been muted (timed out) in **${target.guild.name}** for **${formattedDuration}**.\n**Reason:** ${reason}`,
            }).catch(() => null);
            this.recordInfraction({
                guildId: target.guild.id,
                targetId: target.id,
                targetTag: target.user.tag,
                moderatorId: moderator.id,
                moderatorTag: moderator.user.tag,
                action: "MUTE",
                reason,
                durationMs,
                timestamp: Date.now(),
            });
            await this.loggingService.logTraditionalModAction(target.guild, target.user, moderator.user, "MUTE", reason, formattedDuration);
            return { success: true };
        }
        catch (err) {
            return { success: false, error: err.message };
        }
    }
    /**
     * Issues an official warning to a member
     */
    async warn(moderator, target, reason) {
        try {
            const record = this.recordInfraction({
                guildId: target.guild.id,
                targetId: target.id,
                targetTag: target.user.tag,
                moderatorId: moderator.id,
                moderatorTag: moderator.user.tag,
                action: "WARN",
                reason,
                timestamp: Date.now(),
            });
            const userCases = this.getUserCases(target.guild.id, target.id);
            const warningCount = userCases.filter((c) => c.action === "WARN").length;
            await target.send({
                content: `⚠️ You received an official warning in **${target.guild.name}**.\n**Reason:** ${reason}\n**Total Warnings:** ${warningCount}`,
            }).catch(() => null);
            await this.loggingService.logTraditionalModAction(target.guild, target.user, moderator.user, "WARN", `${reason} (Strike #${warningCount})`);
            return { success: true, warningCount };
        }
        catch (err) {
            return { success: false, warningCount: 0, error: err.message };
        }
    }
    recordInfraction(data) {
        const key = `${data.guildId}:${data.targetId}`;
        const list = this.infractions.get(key) || [];
        const record = {
            ...data,
            caseId: `CASE-${++this.caseCounter}`,
        };
        list.push(record);
        this.infractions.set(key, list);
        this.persistToDisk();
        return record;
    }
    getUserCases(guildId, userId) {
        return this.infractions.get(`${guildId}:${userId}`) || [];
    }
    parseDurationString(input) {
        const match = input.trim().match(/^(\d+)\s*(s|m|h|d|w)$/i);
        if (!match)
            return null;
        const val = parseInt(match[1], 10);
        const unit = match[2].toLowerCase();
        switch (unit) {
            case "s": return val * 1000;
            case "m": return val * 60 * 1000;
            case "h": return val * 60 * 60 * 1000;
            case "d": return val * 24 * 60 * 60 * 1000;
            case "w": return val * 7 * 24 * 60 * 60 * 1000;
            default: return null;
        }
    }
    formatDuration(ms) {
        const seconds = Math.floor(ms / 1000);
        if (seconds < 60)
            return `${seconds} seconds`;
        const minutes = Math.floor(seconds / 60);
        if (minutes < 60)
            return `${minutes} minutes`;
        const hours = Math.floor(minutes / 60);
        if (hours < 24)
            return `${hours} hours`;
        const days = Math.floor(hours / 24);
        return `${days} days`;
    }
}

/**
 * Triage Service
 * High-performance Token Efficiency Pipeline for AegisMod
 * Prevents unnecessary Gemini API calls by pre-filtering 80-90% of benign chat.
 */
export class TriageService {
    cache = new Map();
    CACHE_TTL_MS = 10 * 60 * 1000; // 10 minutes
    benignSlang = new Set([
        "gg", "ggwp", "ggs", "lol", "lmao", "lmfao", "rofl", "w", "l", "fr", "frfr",
        "ong", "ngl", "tbh", "idk", "idc", "brb", "gtg", "gn", "gm", "glhf", "ez",
        "pog", "poggers", "clutch", "sheesh", "bet", "no cap", "cap", "fax", "ok",
        "okay", "k", "sure", "nice", "cool", "ye", "yes", "yea", "yeah", "nah", "no",
        "nope", "hi", "hello", "hey", "yo", "sup", "whatsup", "wassup", "cya", "bye",
        "bro", "bruh", "dude", "man", "mate", "team", "play", "game", "good", "great"
    ]);
    zeroToleranceRegex = /\b(kys|k\.y\.s|kill yourself|kill ur self|die in a fire|suicide|send nudes|send me nudes|trade pics|drop snap 16|drop your insta dm|meet up in person secretly)\b/i;
    /**
     * Evaluates if a message needs Gemini API analysis.
     */
    evaluate(content) {
        const trimmed = content.trim();
        const normalized = trimmed.toLowerCase();
        // Check duplicate in cache
        const cached = this.cache.get(normalized);
        if (cached && Date.now() - cached.timestamp < this.CACHE_TTL_MS) {
            return {
                shouldCallGemini: false,
                localVerdict: cached.result,
                reason: "Cache Hit: Exact duplicate evaluated recently (0 tokens consumed)"
            };
        }
        // 1. Check for single harmless words / short reactions or simple punctuation
        if (this.benignSlang.has(normalized) || /^[\p{Emoji}\s!?.~]{1,4}$/u.test(normalized)) {
            return {
                shouldCallGemini: false,
                localVerdict: {
                    flagged: false,
                    category: "NONE",
                    severity: "NONE",
                    recommendedAction: "ALLOW",
                    reason: "Triage Tier-1: Short benign chat slang or emoji."
                },
                reason: "Fast filter: Benign chat (0 tokens consumed)"
            };
        }
        // 2. All words are known benign chat phrases (< 5 words)
        const words = normalized.split(/\s+/);
        if (words.length <= 5 && words.every(w => this.benignSlang.has(w.replace(/[^a-z]/g, "")))) {
            return {
                shouldCallGemini: false,
                localVerdict: {
                    flagged: false,
                    category: "NONE",
                    severity: "NONE",
                    recommendedAction: "ALLOW",
                    reason: "Triage Tier-1: Multi-word benign slang phrase."
                },
                reason: "Fast filter: Whitelisted conversational phrase (0 tokens consumed)"
            };
        }
        // 3. Instant local regex for zero-tolerance severe hate/predatory patterns
        if (this.zeroToleranceRegex.test(trimmed)) {
            const isSelfHarm = /kys|k\.y\.s|kill yourself|kill ur self|suicide/i.test(trimmed);
            const category = isSelfHarm ? "SELF_HARM" : "SEXUAL_GROOMING_OR_PREDATORY";
            const action = isSelfHarm ? "TIMEOUT_24H" : "BAN";
            const verdict = {
                flagged: true,
                category,
                severity: "CRITICAL",
                recommendedAction: action,
                reason: `Immediate local regex trigger for zero-tolerance keyword pattern in ${category}`
            };
            this.cacheVerdict(normalized, verdict);
            return {
                shouldCallGemini: false,
                localVerdict: verdict,
                reason: "Tier-2 Local Regex Flag: Immediate action without API latency"
            };
        }
        // 4. Default: Require contextual AI analysis from Gemini
        return {
            shouldCallGemini: true,
            reason: "Tier-3 Passed: Message requires nuanced contextual evaluation by Gemini 3.8 Flash."
        };
    }
    cacheVerdict(content, verdict) {
        this.cache.set(content.toLowerCase().trim(), {
            result: verdict,
            timestamp: Date.now()
        });
    }
    clearExpired() {
        const now = Date.now();
        for (const [key, entry] of this.cache.entries()) {
            if (now - entry.timestamp > this.CACHE_TTL_MS) {
                this.cache.delete(key);
            }
        }
    }
}
